    """녹화 원 바이트의 길이와 해시를 확인하고 그대로 반환한다."""
    raw = zlib.decompress(base64.b85decode(_PACKED))
    if len(raw) != RAW_BYTES or hashlib.sha256(raw).hexdigest() != RAW_SHA256:
        raise AssertionError('Lean 녹화 원문 무결성 불일치')
    return raw
